target.css:
:root {
  --cream: #f2ead8;
  --brown-dark: #3b2410;
  --brown-mid: #7a4a1e;
  --brown-light: #c49a5a;
  --rust: #a83c1a;
  --spore-outer: #c49a5a33;
  --spore-mid: #a83c1a22;
  --spore-inner: #7a4a1e44;
  --spore-dot: #3b2410;
  --border-color: #c49a5a;
  --label-bg: #3b2410;
  --label-text: #f2ead8;
  --footer-bg: #7a4a1e;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.spore-card {
  background-color: var(--cream);
  border: 2px solid var(--border-color);
  border-radius: 6px;
  width: 460px;
  padding: 0;
  overflow: hidden;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--label-bg);
  padding: 8px 16px;
}

.card-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--label-text);
  text-transform: uppercase;
}

.card-number {
  font-size: 13px;
  font-weight: 600;
  color: var(--brown-light);
}

.card-body {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 20px 20px 16px 20px;
}

.spore-figure {
  position: relative;
  width: 110px;
  height: 110px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
}

.spore-ring {
  position: absolute;
  border-radius: 50%;
}

.outer-ring {
  width: 110px;
  height: 110px;
  background-color: var(--spore-outer);
  border: 2px solid var(--brown-light);
}

.mid-ring {
  width: 74px;
  height: 74px;
  background-color: var(--spore-mid);
  border: 1px dashed var(--rust);
}

.inner-ring {
  width: 42px;
  height: 42px;
  background-color: var(--spore-inner);
  border: 1px solid var(--brown-mid);
}

.spore-center {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--spore-dot);
  position: absolute;
}

.card-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.detail-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  border-bottom: 1px dotted var(--brown-light);
  padding-bottom: 6px;
}

.detail-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--brown-mid);
  width: 90px;
  flex-shrink: 0;
}

.detail-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--brown-dark);
}

.italic {
  font-style: italic;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background-color: var(--footer-bg);
  padding: 7px 16px;
}

.footer-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--label-text);
  text-transform: uppercase;
}

.footer-initials {
  font-size: 12px;
  font-weight: 600;
  color: var(--brown-light);
  letter-spacing: 0.1em;
}

